importPayload.compose:
# Dokploy: build por URL Git (sem YAML anchors — bake do Dokploy nao resolve *anchor).
# Log deve mostrar: ...pms-project.git#PMS-Backend:backend (backend) e #PMS-Backend (frontend).
services:
  postgres:
    image: postgres:16-alpine
    restart: unless-stopped
    environment:
      POSTGRES_USER: ${POSTGRES_USER:-postgres}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?POSTGRES_PASSWORD obrigatória}
      POSTGRES_DB: ${POSTGRES_DB:-pms}
    volumes:
      - pms_postgres:/var/lib/postgresql/data
    healthcheck:
      test:
        [
          "CMD-SHELL",
          "pg_isready -U ${POSTGRES_USER:-postgres} -d ${POSTGRES_DB:-pms}",
        ]
      interval: 5s
      timeout: 5s
      retries: 20

  redis:
    image: redis:7-alpine
    restart: unless-stopped
    volumes:
      - pms_redis:/data
    expose:
      - "6379"
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 5s
      timeout: 3s
      retries: 20

  backend:
    build:
      context: "https://github.com/ojfernandess/pms-project.git#PMS-Backend:backend"
      dockerfile: Dockerfile
    image: pms-staysos-api
    restart: unless-stopped
    # Dokploy: .env do projeto → env_file repassa todas as vars ao container backend
    env_file:
      - .env
    expose:
      - "3000"
    environment:
      NODE_ENV: production
      PORT: "3000"
      DATABASE_URL: ${DATABASE_URL:?DATABASE_URL obrigatória}
      REDIS_URL: ${REDIS_URL:-redis://redis:6379}
      PRISMA_MIGRATE_ON_START: ${PRISMA_MIGRATE_ON_START:-false}
      JWT_SECRET: ${JWT_SECRET:?JWT_SECRET obrigatório (mín. 32 caracteres)}
      JWT_ACCESS_TTL: ${JWT_ACCESS_TTL:-15m}
      JWT_REFRESH_TTL_DAYS: ${JWT_REFRESH_TTL_DAYS:-7}
      INTERNAL_API_TOKEN: ${INTERNAL_API_TOKEN:-}
      SOCKET_AUTH_TOKEN: ${SOCKET_AUTH_TOKEN:-}
      PUBLIC_APP_URL: ${PUBLIC_APP_URL:-}
      SITE_URL: ${SITE_URL:-}
      CORS_ORIGINS: ${CORS_ORIGINS:-}
      WEB_CHECKIN_PUBLIC_URL: ${WEB_CHECKIN_PUBLIC_URL:-}
      WEB_CHECKIN_PUBLIC_HOST: ${WEB_CHECKIN_PUBLIC_HOST:-}
      WEB_CHECKIN_PUBLIC_HOSTS: ${WEB_CHECKIN_PUBLIC_HOSTS:-}
      PASSWORD_RESET_DEBUG: ${PASSWORD_RESET_DEBUG:-false}
      SUPABASE_URL: ${SUPABASE_URL:-}
      SUPABASE_ANON_KEY: ${SUPABASE_ANON_KEY:-}
      STORAGE_PROVIDER: ${STORAGE_PROVIDER:-local}
      STORAGE_DIR: ${STORAGE_DIR:-/app/storage}
      MINIO_ENDPOINT: ${MINIO_ENDPOINT:-}
      MINIO_PORT: ${MINIO_PORT:-}
      MINIO_USE_SSL: ${MINIO_USE_SSL:-}
      MINIO_ACCESS_KEY: ${MINIO_ACCESS_KEY:-}
      MINIO_SECRET_KEY: ${MINIO_SECRET_KEY:-}
      MINIO_BUCKET: ${MINIO_BUCKET:-}
      MINIO_REGION: ${MINIO_REGION:-us-east-1}
    volumes:
      - pms_storage:/app/storage
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
    healthcheck:
      test:
        [
          "CMD",
          "node",
          "-e",
          "fetch('http://127.0.0.1:3000/health').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))",
        ]
      interval: 30s
      timeout: 5s
      retries: 3
      start_period: 120s

  worker:
    image: pms-staysos-api
    restart: unless-stopped
    command: ["./scripts/docker-entrypoint-worker.sh"]
    environment:
      NODE_ENV: production
      PMS_RUN_MODE: worker
      DATABASE_URL: ${WORKER_DATABASE_URL:-${DATABASE_URL}}
      REDIS_URL: ${REDIS_URL:-redis://redis:6379}
      JWT_SECRET: ${JWT_SECRET}
      JWT_ACCESS_TTL: ${JWT_ACCESS_TTL:-15m}
      JWT_REFRESH_TTL_DAYS: ${JWT_REFRESH_TTL_DAYS:-7}
      INTERNAL_API_TOKEN: ${INTERNAL_API_TOKEN:-}
      SOCKET_AUTH_TOKEN: ${SOCKET_AUTH_TOKEN:-}
      PUBLIC_APP_URL: ${PUBLIC_APP_URL:-}
      SITE_URL: ${SITE_URL:-}
    volumes:
      - pms_storage:/app/storage
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_healthy
      backend:
        condition: service_healthy

  frontend:
    build:
      context: "https://github.com/ojfernandess/pms-project.git#PMS-Backend"
      dockerfile: Dockerfile
      args:
        # Modo B: myapi.* (StayOS) ou Modo A: mesma URL do SPA (PUBLIC_APP_URL)
        VITE_PMS_API_URL: ${VITE_PMS_API_URL:-${PUBLIC_APP_URL:-https://localhost}}
        VITE_SUPABASE_URL: ${VITE_SUPABASE_URL:-}
        VITE_SUPABASE_PUBLISHABLE_KEY: ${VITE_SUPABASE_PUBLISHABLE_KEY:-}
        VITE_APP_URL: ${VITE_APP_URL:-${PUBLIC_APP_URL:-https://localhost}}
        VITE_WEB_CHECKIN_PUBLIC_HOST: ${WEB_CHECKIN_PUBLIC_HOST:-}
    image: pms-staysos-frontend
    restart: unless-stopped
    environment:
      BACKEND_UPSTREAM: ${BACKEND_UPSTREAM:-http://backend:3000}
      # Runtime → deploy/frontend/40-generate-runtime-config.sh (repasse as mesmas vars do painel Dokploy)
      VITE_PMS_API_URL: ${VITE_PMS_API_URL:-}
      PMS_API_URL: ${VITE_PMS_API_URL:-${PMS_API_URL:-}}
      VITE_APP_URL: ${VITE_APP_URL:-}
      PMS_APP_URL: ${PMS_APP_URL:-}
      PMS_APP_URL: ${PMS_APP_URL:-}
      PUBLIC_APP_URL: ${PUBLIC_APP_URL:-}
      SITE_URL: ${SITE_URL:-}
      WEB_CHECKIN_PUBLIC_HOST: ${WEB_CHECKIN_PUBLIC_HOST:-}
      WEB_CHECKIN_PUBLIC_URL: ${WEB_CHECKIN_PUBLIC_URL:-}
      VITE_WEB_CHECKIN_PUBLIC_HOST: ${VITE_WEB_CHECKIN_PUBLIC_HOST:-}
      PLATFORM_DNS_CNAME_TARGET: ${PLATFORM_DNS_CNAME_TARGET:-}
      PLATFORM_DNS_A_TARGET: ${PLATFORM_DNS_A_TARGET:-}
    expose:
      - "80"
    networks:
      - default
      - dokploy-network
    # Rota Traefik extra para checkin.* (PMS continua no domínio principal via Domains do Dokploy)
    labels:
      - traefik.enable=true
      - traefik.docker.network=dokploy-network
      - "traefik.http.routers.pms-frontend-checkin.rule=${WEB_CHECKIN_TRAEFIK_RULE:-Host(`web-checkin-route-disabled.invalid`)}"
      - traefik.http.routers.pms-frontend-checkin.entrypoints=web,websecure
      - traefik.http.routers.pms-frontend-checkin.tls=true
      - traefik.http.routers.pms-frontend-checkin.tls.certresolver=letsencrypt
      - traefik.http.routers.pms-frontend-checkin.service=pms-frontend-checkin-svc
      - traefik.http.services.pms-frontend-checkin-svc.loadbalancer.server.port=80
    depends_on:
      backend:
        condition: service_healthy
    healthcheck:
      test: ["CMD", "wget", "-qO-", "http://127.0.0.1/"]
      interval: 30s
      timeout: 5s
      retries: 3
      start_period: 30s

networks:
  dokploy-network:
    external: true

volumes:
  pms_postgres:
  pms_redis:
  pms_storage:
